settings.markdownTextFunction:
var c = { total: data ? data.length : 0, updated: 0, failed: 0, progress: 0, canceled: 0, idle: 0 };
var prog = ['QUEUED','INITIATED','DOWNLOADING','DOWNLOADED','VERIFIED','UPDATING'];
(data || []).forEach(function (d) {
  var s = ((d && d['fw_state']) || '').toString().toUpperCase();
  if (s === 'UPDATED') c.updated++;
  else if (s === 'FAILED') c.failed++;
  else if (s === 'CANCELED') c.canceled++;
  else if (prog.indexOf(s) >= 0) c.progress++;
  else c.idle++;
});
var active = c.updated + c.failed + c.progress;
var pct = active ? Math.round(100 * c.updated / active) : 0;
function tile(label, val, color) {
  return '<div class="tile"><div class="v" style="color:' + color + '">' + val + '</div><div class="l">' + label + '</div></div>';
}
return '<div class="ota-sum">' +
  tile('Devices', c.total, '#37474f') +
  tile('In progress', c.progress, '#1565c0') +
  tile('Updated', c.updated, '#2e7d32') +
  tile('Failed', c.failed, '#c62828') +
  tile('Stopped', c.canceled, '#616161') +
  tile('No OTA / idle', c.idle, '#757575') +
  '<div class="tile wide"><div class="l">Rollout completion</div>' +
  '<div class="bar"><div class="fill" style="width:' + pct + '%"></div></div>' +
  '<div class="l">' + pct + '% of devices in rollout updated</div></div>' +
  '</div>';

settings.cellStyleFunction:
var s = (value || '').toString().toUpperCase();
var c = { UPDATED:'#2e7d32', FAILED:'#c62828', QUEUED:'#6d4c41', INITIATED:'#5e35b1',
          DOWNLOADING:'#1565c0', DOWNLOADED:'#00838f', VERIFIED:'#00695c', UPDATING:'#ef6c00', CANCELED:'#616161' }[s];
