customDialog.customDialog(htmlTemplate, ManageController).subscribe();

function ManageController(instance) {
  let vm = instance;
  vm.rows = []; vm.busy = true; vm.status = '';
  vm.cancel = function () { widgetContext.updateAliases(); vm.dialogRef.close(null); };

  vm.load = async function () {
    vm.busy = true;
    try {
      const pk = await toP(http.get('/api/otaPackages?pageSize=500&page=0&sortProperty=createdTime&sortOrder=DESC'));
      const pr = await toP(http.get('/api/deviceProfiles?pageSize=500&page=0'));
      vm.profiles = {};
      (pr.data || []).forEach(p => vm.profiles[p.id.id] = p);
      vm.rows = (pk.data || []).filter(p => p.type === 'FIRMWARE').map(p => {
        const prof = p.deviceProfileId ? vm.profiles[p.deviceProfileId.id] : null;
        return { pkg: p, profile: prof, profileName: prof ? prof.name : '-',
                 active: !!(prof && prof.firmwareId && prof.firmwareId.id === p.id.id) };
      });
    } catch (e) { vm.status = 'Error: ' + errMsg(e); }
    vm.busy = false;
  };

  vm.stopRollout = async function (r) {
    if (!confirm('Stop rollout of ' + r.pkg.title + ' v' + r.pkg.version + ' for profile "' + r.profileName + '"?')) { return; }
    vm.busy = true;
    try {
      const res = await stopProfileRollout(r.profile);
      vm.status = 'Rollout stopped: ' + res.devices + ' device(s) unassigned, ' + res.canceled + ' in-progress update(s) marked CANCELED.';
    } catch (e) { vm.status = 'Error: ' + errMsg(e); }
    await vm.load();
  };

  vm.remove = async function (r) {
    const label = r.pkg.title + ' v' + r.pkg.version;
    const msg = r.active
      ? label + ' is the active rollout for profile "' + r.profileName + '". Stop the rollout and delete it permanently?'
      : 'Delete ' + label + ' permanently?';
    if (!confirm(msg)) { return; }
    vm.busy = true;
    try {
      if (r.active) { await stopProfileRollout(r.profile); }
      await toP(http.delete('/api/otaPackage/' + r.pkg.id.id));
      vm.status = 'Deleted ' + label + '.';
    } catch (e) {
      vm.status = 'Error: ' + errMsg(e) +
        '\nIf the package is still assigned to individual devices, use "Assign / start OTA" or "Stop OTA" on those devices first.';
    }
    await vm.load();
  };

  vm.load();
}

