customDialog.customDialog(htmlTemplate, AssignController).subscribe();

function AssignController(instance) {
  let vm = instance;
  vm.deviceName = entityName;
  vm.device = null;
  vm.packages = [];
  vm.busy = true;
  vm.status = 'Loading...';
  vm.form = vm.fb.group({ packageId: [null] });

  toP(http.get('/api/device/' + entityId.id))
    .then(dev => {
      vm.device = dev;
      vm.form.patchValue({ packageId: dev.firmwareId ? dev.firmwareId.id : null });
      return toP(http.get('/api/otaPackages/' + dev.deviceProfileId.id + '/FIRMWARE?pageSize=200&page=0&sortProperty=createdTime&sortOrder=DESC'));
    })
    .then(r => {
      vm.packages = (r.data || []).filter(p => p.hasData !== false);
      vm.busy = false;
      vm.status = vm.packages.length ? '' : 'No firmware uploaded for this device profile yet.';
    })
    .catch(e => { vm.busy = false; vm.status = 'Error: ' + errMsg(e); });

  vm.cancel = function () { vm.dialogRef.close(null); };

  vm.save = async function () {
    if (!vm.device || vm.busy) { return; }
    vm.busy = true;
    vm.status = 'Saving...';
    try {
      const id = vm.form.value.packageId;
      vm.device.firmwareId = id ? { entityType: 'OTA_PACKAGE', id: id } : null;
      await toP(http.post('/api/device', vm.device));
      vm.status = 'Updating HTTP download link (fw_url)...';
      if (id) {
        await setFwUrl(vm.device.id.id, vm.packages.find(p => p.id.id === id));
      } else {
        const prof = await toP(http.get('/api/deviceProfile/' + vm.device.deviceProfileId.id));
        if (prof.firmwareId) {
          await setFwUrl(vm.device.id.id, await toP(http.get('/api/otaPackage/info/' + prof.firmwareId.id)));
        } else {
          await clearFwUrl(vm.device.id.id);
        }
      }
      widgetContext.updateAliases();
      vm.dialogRef.close(null);
    } catch (e) {
      vm.busy = false;
      vm.status = 'Error: ' + errMsg(e);
    }
  };
}

