function StopController(instance) {
  let vm = instance;
  vm.deviceName = entityName;
  vm.busy = true; vm.loaded = false; vm.status = 'Loading...';
  vm.form = vm.fb.group({ scope: [null] });
  vm.cancel = function () { vm.dialogRef.close(null); };

  (async function load() {
    try {
      vm.device = await toP(http.get('/api/device/' + entityId.id));
      vm.profile = await toP(http.get('/api/deviceProfile/' + vm.device.deviceProfileId.id));
      vm.profileName = vm.profile.name;
      const ts = await toP(http.get('/api/plugins/telemetry/DEVICE/' + entityId.id +
                 '/values/timeseries?keys=fw_state,current_fw_title,current_fw_version'));
      const val = k => (ts && ts[k] && ts[k][0]) ? String(ts[k][0].value) : '';
      vm.state = val('fw_state').toUpperCase();
      const curT = val('current_fw_title'), curV = val('current_fw_version');
      vm.running = curT || curV ? (curT + ' ' + curV).trim() : '';
