      vm.packages = pk.data || [];
      const name = id => { const p = vm.packages.find(x => x.id.id === id); return p ? p.title + ' v' + p.version : id; };
      vm.deviceFwName = vm.device.firmwareId ? name(vm.device.firmwareId.id) : '';
      vm.profileFwName = vm.profile.firmwareId ? name(vm.profile.firmwareId.id) : '';
      vm.match = vm.packages.find(p => p.title === curT && p.version === curV);
      vm.canStopDevice = !vm.profile.firmwareId || !!vm.match;
      vm.form.patchValue({ scope: vm.canStopDevice ? 'device' : (vm.profileFwName ? 'profile' : null) });
      vm.loaded = true; vm.busy = false; vm.status = '';
    } catch (e) { vm.busy = false; vm.status = 'Error: ' + errMsg(e); }
  })();

  vm.save = async function () {
    if (vm.busy) { return; }
    vm.busy = true;
    try {
      if (vm.form.value.scope === 'device') {
        vm.status = 'Removing target firmware from device...';
        // No profile firmware -> clear assignment. Profile firmware present -> pin device to the version it already runs.
        vm.device.firmwareId = vm.profile.firmwareId ? { entityType: 'OTA_PACKAGE', id: vm.match.id.id } : null;
        await toP(http.post('/api/device', vm.device));
        await clearFwUrl(vm.device.id.id);
        await sleep(3000); // let ThingsBoard finish its own state writes first
        await markCanceled(vm.device.id.id, false);
        vm.status = 'OTA stopped for ' + vm.deviceName + '.';
      } else {
        if (!confirm('Stop the rollout of ' + vm.profileFwName + ' for ALL devices of profile "' + vm.profileName + '"?')) {
          vm.busy = false; return;
        }
        vm.status = 'Stopping profile rollout...';
        const r = await stopProfileRollout(vm.profile);
        if (vm.device.firmwareId) {
          vm.device.firmwareId = null;
          await toP(http.post('/api/device', vm.device));
          await clearFwUrl(vm.device.id.id);
          await markCanceled(vm.device.id.id, false);
        }
        vm.status = 'Rollout stopped. ' + r.devices + ' device(s) unassigned, ' + r.canceled + ' in-progress update(s) marked CANCELED.';
      }
      widgetContext.updateAliases();
      vm.busy = false; vm.loaded = false;
    } catch (e) { vm.busy = false; vm.status = 'Error: ' + errMsg(e); }
  };
}

let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap.get('customDialog'));
const http = widgetContext.http;
const toP = o => new Promise((res, rej) => o.subscribe({ next: res, error: rej }));
const errMsg = e => (e && e.error && e.error.message) || (e && e.message) || (e && e.statusText) || 'Unknown error';

// Base URL devices use to reach the ThingsBoard HTTP transport.
// Default = same host/port as this UI. Change if devices use a different host, port or a public domain.
const HTTP_BASE = window.location.origin;
const ACTIVE = ['QUEUED','INITIATED','DOWNLOADING','DOWNLOADED','VERIFIED','UPDATING'];
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function getToken(deviceId) {
  const c = await toP(http.get('/api/device/' + deviceId + '/credentials'));
  return c && c.credentialsType === 'ACCESS_TOKEN' ? c.credentialsId : null;
}
function fwDownloadUrl(token, pkg) {
  return HTTP_BASE + '/api/v1/' + token + '/firmware?title=' + encodeURIComponent(pkg.title) +
         '&version=' + encodeURIComponent(pkg.version);
}
function pollUrl(token) {
  return HTTP_BASE + '/api/v1/' + token +
    '/attributes?sharedKeys=fw_title,fw_version,fw_size,fw_checksum,fw_checksum_algorithm,fw_url';
}
async function setFwUrl(deviceId, pkg) {
  const t = await getToken(deviceId);
  if (!t) { return; }
  await toP(http.post('/api/plugins/telemetry/DEVICE/' + deviceId + '/attributes/SHARED_SCOPE',
                      { fw_url: fwDownloadUrl(t, pkg) }));
}
async function clearFwUrl(deviceId) {
  try { await toP(http.delete('/api/plugins/telemetry/DEVICE/' + deviceId + '/SHARED_SCOPE?keys=fw_url')); } catch (e) {}
}
async function markCanceled(deviceId, onlyIfActive) {
  if (onlyIfActive) {
    const r = await toP(http.get('/api/plugins/telemetry/DEVICE/' + deviceId + '/values/timeseries?keys=fw_state'));
    const s = (r && r.fw_state && r.fw_state[0]) ? String(r.fw_state[0].value).toUpperCase() : '';
    if (ACTIVE.indexOf(s) < 0) { return false; }
  }
  await toP(http.post('/api/plugins/telemetry/DEVICE/' + deviceId + '/timeseries/ANY',
                      { fw_state: 'CANCELED', fw_error: 'Stopped by operator' }));
  return true;
}
async function devicesOfProfile(profileId) {
  let out = [], page = 0, more = true;
  while (more) {
    const r = await toP(http.get('/api/tenant/deviceInfos?pageSize=500&page=' + page + '&deviceProfileId=' + profileId));
    out = out.concat(r.data || []); more = !!r.hasNext; page++;
  }
  return out;
}
// Devices without a device-level firmware override follow the profile firmware
async function setProfileFwUrls(profileId, pkg) {
  const devs = (await devicesOfProfile(profileId)).filter(d => !d.firmwareId);
  for (const d of devs) { await setFwUrl(d.id.id, pkg); }
  return devs.length;
}
async function stopProfileRollout(profile) {
  profile.firmwareId = null;
  await toP(http.post('/api/deviceProfile', profile));
  const devs = (await devicesOfProfile(profile.id.id)).filter(d => !d.firmwareId);
  let canceled = 0;
  for (const d of devs) {
    await clearFwUrl(d.id.id);
    if (await markCanceled(d.id.id, true)) { canceled++; }
  }
  return { devices: devs.length, canceled: canceled };
}

customDialog.customDialog(htmlTemplate, PollController).subscribe();

function PollController(instance) {
  let vm = instance;
  vm.deviceName = entityName; vm.links = []; vm.busy = true; vm.status = 'Loading...'; vm.copied = '';
  vm.cancel = function () { vm.dialogRef.close(null); };
  vm.copy = function (t) {
    navigator.clipboard.writeText(t).then(() => vm.copied = 'Copied to clipboard', () => vm.copied = 'Copy failed, select the text manually');
  };

  (async function () {
    try {
      const token = await getToken(entityId.id);
      if (!token) { vm.busy = false; vm.status = 'Error: this device does not use ACCESS_TOKEN credentials, which the HTTP API requires.'; return; }
      const dev = await toP(http.get('/api/device/' + entityId.id));
      let fwId = dev.firmwareId;
      if (!fwId) { const prof = await toP(http.get('/api/deviceProfile/' + dev.deviceProfileId.id)); fwId = prof.firmwareId; }
      const pkg = fwId ? await toP(http.get('/api/otaPackage/info/' + fwId.id)) : null;
      const ex = pkg || { title: 'sambhav-fw', version: '1.2.0', dataSize: 245760, checksum: '<sha256>', checksumAlgorithm: 'SHA256' };
      vm.links = [
        { label: '1. Poll for updates', method: 'GET', url: pollUrl(token),
          note: 'Update available if shared.fw_url is present and shared.fw_version differs from the running version.' },
        { label: '2. Download binary (the fw_url value)', method: 'GET',
          url: pkg ? fwDownloadUrl(token, pkg) : HTTP_BASE + '/api/v1/' + token + '/firmware?title=<fw_title>&version=<fw_version>',
          note: 'Append &size=4096&chunk=0,1,2... to fetch in chunks (useful for modem RAM limits). Verify fw_checksum before flashing.' },
        { label: '3. Report OTA state', method: 'POST', url: HTTP_BASE + '/api/v1/' + token + '/telemetry',
          note: 'Body e.g. {"fw_state":"DOWNLOADING"} ... {"fw_state":"UPDATED"}, or {"fw_state":"FAILED","fw_error":"checksum mismatch"}. After reboot send {"current_fw_title":"...","current_fw_version":"..."}.' },
        { label: 'Optional: long-poll instead of periodic polling', method: 'GET',
          url: HTTP_BASE + '/api/v1/' + token + '/attributes/updates?timeout=30000',
          note: 'The request is held open up to 30 s and returns as soon as shared attributes change (e.g. fw_url set or deleted).' }
      ];
      vm.example = JSON.stringify({ shared: {
        fw_title: ex.title, fw_version: ex.version, fw_size: ex.dataSize,
        fw_checksum: ex.checksum, fw_checksum_algorithm: ex.checksumAlgorithm,
        fw_url: fwDownloadUrl(token, ex) } }, null, 2);
      vm.busy = false; vm.status = '';
    } catch (e) { vm.busy = false; vm.status = 'Error: ' + errMsg(e); }
  })();
}

settings.markdownTextFunction:
var d = (data && data[0]) || {};
var s = (d['fw_state'] || '-').toString().toUpperCase();
var steps = ['QUEUED','INITIATED','DOWNLOADING','DOWNLOADED','VERIFIED','UPDATING','UPDATED'];
var idx = steps.indexOf(s);
var col = s === 'CANCELED' ? '#616161' : s === 'FAILED' ? '#c62828' : (s === 'UPDATED' ? '#2e7d32' : '#1565c0');
var track = steps.map(function (st, i) {
  var done = idx >= 0 && i <= idx;
  return '<div class="st ' + (done ? 'done' : '') + '">' + st + '</div>';
}).join('');
var done = (s === 'UPDATED' && d['current_fw_version'] && d['current_fw_version'] === d['fw_version']);
return '<div class="dv">' +
  '<div class="row"><div><span class="l">Running</span><b>' + (d['current_fw_title'] || '-') + ' ' + (d['current_fw_version'] || '') + '</b></div>' +
  '<div><span class="l">Target</span><b>' + (d['fw_title'] || '-') + ' ' + (d['fw_version'] || '') + '</b></div>' +
  '<div><span class="l">State</span><b style="color:' + col + '">' + s + '</b></div>' +
  '<div><span class="l">Completion</span><b style="color:' + (done ? '#2e7d32' : '#757575') + '">' + (done ? 'COMPLETE' : (s === 'FAILED' ? 'FAILED' : (s === 'CANCELED' ? 'STOPPED' : 'PENDING'))) + '</b></div></div>' +
  '<div class="track">' + track + '</div>' +
  (d['fw_error'] ? '<div class="err">Error: ' + d['fw_error'] + '</div>' : '') +
  (d['fw_url'] ? '<div style="font-size:12px;word-break:break-all;"><span class="l">HTTP download (fw_url): </span>' + d['fw_url'] + '</div>' : '') +
  '</div>';

